-- PT120-S3-Q22. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT120-S3-Q22$batch09$ AND q.stimulus=$batch09$If one does not have enough information to make a well-informed decision, one should not make a decision solely on the basis of the information one does possess. Instead, one should continue to seek information until a well-informed decision can be made.$batch09$ AND q.prompt=$batch09$Of the following, which one most closely conforms to the principle stated above?$batch09$ AND q.correct_choice=$batch09$D$batch09$) THEN RAISE EXCEPTION 'Question changed: PT120-S3-Q22'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT120-S3-Q22$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S3-Q22'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT120-S3-Q22$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$If you don't have enough information for a well-informed decision, don't decide on what you have. Keep seeking information until you can decide well.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$A conforming choice needs both halves. First, the information on hand is inadequate. Second, the response is to go get more information before deciding. A choice that says "think harder about what you already have" or "give up" doesn't conform.$batch09$), (2, $batch09$Goal$batch09$, $batch09$Someone with inadequate information who goes and gets more before deciding.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT120-S3-Q22$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This says not to trust one model because conflicting models can't all be right. It never says to keep looking for information before deciding.$batch09$), ($batch09$B$batch09$, $batch09$This is a trap, picked by 11%. It warns against deciding on one factor alone. But its fix is to weigh the information you already have more carefully. The rule says that when your information is inadequate, you should go out and get more.$batch09$), ($batch09$C$batch09$, $batch09$This is the most-picked trap, at 12%. It sounds like the rule because it urges looking for more information. But the rule is triggered by a specific situation: not enough information to make a decision. C has no decision and says "always" look, even when the researcher may know enough. That's a general habit, not this rule.$batch09$), ($batch09$D$batch09$, $batch09$Personal experience is called an "inadequate basis," which is the trigger. Studying reliability histories from many owners is seeking more information before choosing a car. Both halves are there.$batch09$), ($batch09$E$batch09$, $batch09$This has the trigger: not enough information. But then it says to give up and admit the meaning can't be found. The rule says to keep looking.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT120-S3-Q22$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
